import torch.nn as nn
class Cell(nn.Module):
    def __init__(self):
        super().__init__()
        shared=nn.Identity()
        self.stages=nn.ModuleList([shared,shared,None])
    def helper(self):
        self.stages=nn.ModuleList([])
    def forward(self,sample):
        self.helper()
        for index,block in enumerate(self.stages):
            if block is not None:
                sample=block(sample)
        return sample

